package com.retail.payment.repository;

import com.retail.payment.entity.CustomerPaymentMethod;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.rest.core.annotation.RepositoryRestResource;
import org.springframework.data.rest.core.annotation.RestResource;
import org.springframework.security.access.prepost.PostAuthorize;
import org.springframework.security.access.prepost.PreAuthorize;
import java.util.Optional;

@RepositoryRestResource(collectionResourceRel = "payment-methods", path = "payment-methods")
public interface CustomerPaymentMethodRepository extends JpaRepository<CustomerPaymentMethod, Long> {

    @Override
    @PostAuthorize("returnObject.isPresent() and returnObject.get().customerUsername == principal.username")
    Optional<CustomerPaymentMethod> findById(Long id);

    @Override
    @PreAuthorize("#entity.customerUsername == principal.username")
    <S extends CustomerPaymentMethod> S save(S entity);

    @Override
    @RestResource(exported = false)
    void deleteById(Long id);
}
